export function getArticleBySlug(slug: string): SEOArticle | undefined {
  return SEO_ARTICLES.find((a) => a.slug === slug);
}

export function getArticlesByCategory(category: string): SEOArticle[] {
  if (category === "All") return SEO_ARTICLES;
  return SEO_ARTICLES.filter((a) => a.category === category);
}

export function getFeaturedArticles(): SEOArticle[] {
  return SEO_ARTICLES.filter((a) => a.featured);
}

export function getRelatedArticles(currentSlug: string, count = 4): SEOArticle[] {
  const current = getArticleBySlug(currentSlug);
  if (!current) return SEO_ARTICLES.slice(0, count);
  return SEO_ARTICLES
    .filter((a) => a.slug !== currentSlug && (a.category === current.category || a.location === current.location))
    .slice(0, count);
}
